import json
from pathlib import Path

compositions = ['Li3N', 'Na3N', 'Mg3N2', 'Ca3N2', 'Sr3N2', 'Ba3N2', 'BN', 'AlN', 'GaN', 'InN', 'TiN', 'ZrN', 'HfN', 'Ti2N', 'Zr2N', 'VN', 'NbN', 'TaN', 'V2N', 'Nb2N', 'CrN', 'MoN', 'WN', 'Cr2N', 'Mo2N', 'MnN', 'FeN', 'CoN', 'NiN', 'CuN', 'Fe2N', 'Fe3N', 'Fe4N', 'MgSiN2', 'CaSiN2']

filtered_data = []
base_path = Path('../CORRAL_WORK_DIR/ml_ujqraq/ml_nitrides_trial_7/polymorph_data')

for comp in compositions:
    file_path = base_path / f'{comp}_polymorphs.json'
    if file_path.exists():
        try:
            with open(file_path, 'r') as f:
                comp_data = json.load(f)
                for item in comp_data:
                    item['source_composition'] = comp
                filtered_data.extend(comp_data)
        except:
            pass

